// S7F43 creates the S7F43 (Large Formatted Process Program Request) message, direction: bidirectional.
//
// This message is used to request the transfer of a formatted process program via the Data Set Transfer protocol.
// The Data Set name, DSNAME, is the text string identifier of the process program, PPID.
// The Data Set is subsequently transferred as a Stream whose internal SECS-II structured data is the formatted process program L,4 {PPID, MDLN, SOFTREV, L,c {L,2 {CCODE, L,p {PPARM}}}}.
//
// Body: A[dsname].
//
// Exception: None.
func S7F43(dsname string) secs2.SECS2Message {
	return secs2.NewMessage(7, 43, true, secs2.A(dsname))
}

// S7F44 creates the S7F44 (Large Formatted Process Program Acknowledge) message, direction: bidirectional.
//
// Acknowledge or error.
// A returned status of "accepted" means only that the message is understood.
// When the receiving entity is the equipment, there is a separate verification transaction (S7F27/S7F28)
// that indicates the completion status of the request.
// When the receiving entity is the host, the completion of the request is signaled by an event report.
//
// Body: B[ackc7].
//
// Exception: It is possible to use the ACKC7 code "command will be performed with completion signaled later" for this message.
func S7F44(ackc7 ACKC7) secs2.SECS2Message {
	return secs2.NewMessage(7, 44, false, secs2.B(byte(ackc7)))
}
